window.docContents[202].resolve({"/2___-Basic-notions-of-representation-theory/2___16___-Problems-on-Lie-algebras/Lie-algebras-defined-by-ad-relations/#Chapter2___Problem2___16___3":{"contents":"Problem 2.16.3. (Hard!) For any element x of a Lie algebra \\mathfrak{g} let \\operatorname{ad}(x) denote the operator \\mathfrak{g} \\to \\mathfrak{g}, y \\mapsto [x, y]. Consider the Lie algebra \\mathfrak{g}_n generated by two elements x, y with the defining relations \\operatorname{ad}(x)^2(y) = \\operatorname{ad}(y)^{n+1}(x) = 0.\n\n(a) Show that the Lie algebras \\mathfrak{g}_1, \\mathfrak{g}_2, \\mathfrak{g}_3 are finite dimensional and find their dimensions.\n\n(b) (Harder!) Show that the Lie algebra \\mathfrak{g}_4 has infinite dimension. Construct explicitly a basis of this algebra.\n\n\n\n","context":"Introduction to Representation Theory\t2. Basic notions of representation theory\t2.16. Problems on Lie algebras\tLie algebras defined by ad relations","header":"Lie algebras defined by ad relations","id":"/2___-Basic-notions-of-representation-theory/2___16___-Problems-on-Lie-algebras/Lie-algebras-defined-by-ad-relations/#Chapter2___Problem2___16___3"},"/3___-General-results-of-representation-theory/3___3___-Representations-of-direct-sums-of-matrix-algebras/Motivation-for-dual-representations-in-proof-of-Theorem-3___3___1/#Chapter3___Discussion_before_Definition3___3___2":{"contents":"In order to prove Theorem 3.3.1, we shall need the notion of a dual representation.\n\n\n","context":"Introduction to Representation Theory\t3. General results of representation theory\t3.3. Representations of direct sums of matrix algebras\tMotivation for dual representations in proof of Theorem 3.3.1","header":"Motivation for dual representations in proof of Theorem 3.3.1","id":"/3___-General-results-of-representation-theory/3___3___-Representations-of-direct-sums-of-matrix-algebras/Motivation-for-dual-representations-in-proof-of-Theorem-3___3___1/#Chapter3___Discussion_before_Definition3___3___2"},"/6___-Quiver-representations/6___7___-Coxeter-elements/#chapter-06___section-6-7":{"contents":"\n\n\n\n\n\n","context":"Introduction to Representation Theory\t6. Quiver representations","header":"6.7. Coxeter elements","id":"/6___-Quiver-representations/6___7___-Coxeter-elements/#chapter-06___section-6-7"}});
